-- AlterTable
ALTER TABLE "currencies" ADD COLUMN "region" TEXT;

-- Ajout des devises africaines (et mise à jour des devises déjà présentes).
-- Les taux sont des valeurs de secours, remplacées ensuite par les taux en temps réel.
ON CONFLICT ("code") DO UPDATE SET
    "name" = EXCLUDED."name",
    "symbol" = EXCLUDED."symbol",
    "flagEmoji" = EXCLUDED."flagEmoji",
    "region" = EXCLUDED."region",
    "rateToXof" = EXCLUDED."rateToXof",
    "updated_at" = CURRENT_TIMESTAMP;
